"""Contract tests for the feedstock generated by the default Copier answers."""

import ast
import hashlib
from pathlib import Path

GENERATED = Path(__file__).parent / "regression" / "ctt" / "defaults"


def test_generated_feedstock_uses_record_and_replay_shape() -> None:
    """The generated project exposes the resolved record and replay contract."""
    recipe = (GENERATED / "bookshelf.yaml").read_text()
    build = (GENERATED / "build.py").read_text()
    pyproject = (GENERATED / "pyproject.toml").read_text()
    ruff = (GENERATED / "ruff.toml").read_text()
    makefile = (GENERATED / "Makefile").read_text()

    assert "collection: example" in recipe
    assert "notebook: build.py" in recipe
    assert 'version = "v0.1.0"' in build
    assert 'input_sha256 = "sha256:' in build
    assert 'Path(".cache")' in build
    assert "recorder, book = bookshelf.setup(version=version" in build
    assert "used=[raw.tracking_id]" in build
    assert '"bookshelf-client[cli,publish,dataframes]' in pyproject
    assert '"build.py" = [' in ruff
    assert '"E402"' in ruff
    assert 'src = [\n    ".",' in ruff
    assert 'known-first-party = [\n    "build",' in ruff
    assert "scripts/validate-bundle.py" in makefile
    assert (GENERATED / "scripts" / "validate-bundle.py").exists()


def test_generated_example_input_matches_its_declared_content_hash() -> None:
    """The cached example input is independently verified by the contract test."""
    tree = ast.parse((GENERATED / "build.py").read_text())
    assignments = {
        node.targets[0].id: ast.literal_eval(node.value)
        for node in tree.body
        if isinstance(node, ast.Assign)
        and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
        and node.targets[0].id in {"input_content", "input_sha256"}
    }

    actual = "sha256:" + hashlib.sha256(assignments["input_content"]).hexdigest()
    assert actual == assignments["input_sha256"]


def test_generated_feedstock_calls_reusable_workflows() -> None:
    """The generated project owns triggers and delegates workflow implementation."""
    workflows = GENERATED / ".github" / "workflows"
    ci = (workflows / "feedstock-ci.yaml").read_text()
    publish = (workflows / "feedstock-publish.yaml").read_text()

    assert "pull_request:" in ci
    assert "push:" in ci
    assert "schedule:" in ci
    assert (
        "climate-resource/copier-bookshelf-dataset/.github/workflows/"
        "feedstock-ci.yaml@HEAD" in ci
    )
    assert "release:" in publish
    assert "workflow_dispatch:" in publish
    assert (
        "climate-resource/copier-bookshelf-dataset/.github/workflows/"
        "feedstock-publish.yaml@HEAD" in publish
    )
    assert "secrets: inherit" in publish
    assert "BOOKSHELF_CLIENT_ID:" not in publish
    assert "BOOKSHELF_CLIENT_SECRET:" not in publish


def test_caller_templates_derive_the_reusable_workflow_ref() -> None:
    """A caller uses Copier's selected ref, with its resolved commit as fallback."""
    template_workflows = (
        Path(__file__).parents[1] / "template" / ".github" / "workflows"
    )

    for name in ("feedstock-ci.yaml.jinja", "feedstock-publish.yaml.jinja"):
        caller = (template_workflows / name).read_text()
        assert "_copier_conf.vcs_ref or _copier_answers._commit" in caller
